// src/provision/pnpm-installer.ts
var DEFAULT_PNPM_VERSION = "10.33.0";
var INSTALL_TIMEOUT_MS2 = 3e5;
async function ensurePnpm(ctx, options) {
  const { registryUrl, nodeBinDir, signal } = options;
  const { transport, paths } = ctx;
  const version = DEFAULT_PNPM_VERSION;
  const existing = await transport.exec(
    `pnpm -v 2>/dev/null || true`,
    { pathPrefix: nodeBinDir, allowNonZeroExit: true, ...signal ? { signal } : {} }
  );
  if (existing.stdout.trim() === version) {
    return { version, reused: true };
  }
  options.onProgress?.(`\u5B89\u88C5 pnpm ${version}`);
  const install = lockInstallCommand(paths, [
    `npm install -g --prefix ${quote(nodeBinDirOf(nodeBinDir))}`,
    `--registry=${quote(registryUrl)} --no-audit --no-fund ${quote(`pnpm@${version}`)}`
  ].join(" "));
  try {
    await transport.exec(install, {
      pathPrefix: nodeBinDir,
      env: { npm_config_cache: paths.npmCache },
      timeoutMs: INSTALL_TIMEOUT_MS2 + 6e4,
      ...signal ? { signal } : {}
    });
  } catch (error) {
    const hint = installLockHint(String(error.stderr ?? ""));
    throw new RemoteError(
      "EXEC_FAILED",
      `\u5728\u4E3B\u673A ${transport.hostAlias} \u4E0A\u5B89\u88C5 pnpm ${version} \u5931\u8D25${hint ?? ""}`,
      { cause: error, hostAlias: transport.hostAlias }
    );
  }
  const verify = await transport.exec(`pnpm -v`, {
    pathPrefix: nodeBinDir,
    ...signal ? { signal } : {}
  });
  const actual = verify.stdout.trim();
  if (actual !== version) {
    throw new RemoteError(
      "EXEC_FAILED",
      `\u4E3B\u673A ${transport.hostAlias} \u4E0A\u5B89\u88C5\u7684 pnpm \u7248\u672C\u4E0D\u7B26\uFF1A\u671F\u671B ${version}\uFF0C\u5B9E\u9645 ${actual || "(\u65E0\u8F93\u51FA)"}`,
      { hostAlias: transport.hostAlias }
    );
  }
  return { version, reused: false };
}
function nodeBinDirOf(nodeBinDir) {
  return nodeBinDir.endsWith("/bin") ? nodeBinDir.slice(0, -"/bin".length) : nodeBinDir;
}

// src/provision/profile-writer.ts
var SESSION_PROFILE_NAME = "web";
var INIT_TIMEOUT_MS = 3e5;
async function prepareSessionProfile(ctx, options) {
  const { sessionId, dshBin, nodeBinDir, signal } = options;
  const { transport, paths } = ctx;
  const dshHome = paths.sessionHome(sessionId);
  const profileDir = paths.sessionProfile(sessionId);
  const runtimeDir = paths.sessionRuntime(sessionId);
  await transport.exec(`mkdir -p ${quote(runtimeDir)}`, {
    ...signal ? { signal } : {}
  });
  const hostProfileDir = paths.hostProfileDir(SESSION_PROFILE_NAME);
  const hostMarker = `${hostProfileDir}/package.json`;
  const hostCheck = await transport.exec(
    `test -f ${quote(hostMarker)} && echo EXISTS || true`,
    { allowNonZeroExit: true, ...signal ? { signal } : {} }
  );
  const hostExists = hostCheck.stdout.includes("EXISTS");
  if (!hostExists) {
    options.onProgress?.("\u521D\u59CB\u5316\u4E3B\u673A\u7EA7 profile");
    const init = [
      quote(dshBin),
      "--profile",
      quote(SESSION_PROFILE_NAME),
      "--dump-config"
    ].join(" ");
    try {
      await transport.exec(`${init} >/dev/null`, {
        env: { DSH_HOME: paths.base },
        pathPrefix: nodeBinDir,
        timeoutMs: INIT_TIMEOUT_MS,
        ...signal ? { signal } : {}
      });
    } catch (error) {
      throw new RemoteError(
        "EXEC_FAILED",
        `\u5728\u4E3B\u673A ${transport.hostAlias} \u4E0A\u521D\u59CB\u5316\u4E3B\u673A\u7EA7 profile \u5931\u8D25`,
        { cause: error, hostAlias: transport.hostAlias }
      );
    }
    const verify = await transport.exec(
      `test -f ${quote(hostMarker)} && echo EXISTS || true`,
      { allowNonZeroExit: true, ...signal ? { signal } : {} }
    );
    if (!verify.stdout.includes("EXISTS")) {
      throw new RemoteError(
        "EXEC_FAILED",
        `\u521D\u59CB\u5316\u540E\u4E3B\u673A ${transport.hostAlias} \u4E0A\u4ECD\u672A\u751F\u6210 host profile\uFF1A${hostMarker}`,
        { hostAlias: transport.hostAlias }
      );
    }
  }
  const sessionMarker = `${profileDir}/package.json`;
  const sessionCheck = await transport.exec(
    `test -L ${quote(profileDir)} && echo SYMLINK || test -f ${quote(sessionMarker)} && echo EXISTS || true`,
    { allowNonZeroExit: true, ...signal ? { signal } : {} }
  );
  const reused = sessionCheck.stdout.includes("SYMLINK") || sessionCheck.stdout.includes("EXISTS");
  if (!sessionCheck.stdout.includes("SYMLINK")) {
    const parentDir = profileDir.substring(0, profileDir.lastIndexOf("/"));
    const linkScript = [
      `mkdir -p ${quote(parentDir)}`,
      `[ -d ${quote(profileDir)} ] && rm -rf ${quote(profileDir)}`,
      `ln -sfn ${quote(hostProfileDir)} ${quote(profileDir)}`
    ].join("\n");
    await transport.exec(linkScript, { allowNonZeroExit: true, ...signal ? { signal } : {} });
  }
  let patchFile;
  if (options.patches && options.patches.length > 0) {
    patchFile = paths.sessionPatchFile(sessionId);
    const yaml = renderPatchYaml(options.patches);
    await writeRemoteTextFile(transport, patchFile, yaml, signal ? { signal } : {});
  }
  return {
    dshHome,
    profileName: SESSION_PROFILE_NAME,
    ...patchFile ? { patchFile } : {},
    reused
  };
}
function renderPatchYaml(patches) {
  const lines = [];
  for (const patch of patches) {
    lines.push(`- id: ${patch.id}`);
    lines.push("  config:");
    for (const [key, value] of Object.entries(patch.config)) {
      lines.push(`    ${key}: ${renderScalar(value)}`);
    }
  }
  return `${lines.join("\n")}
`;
}
function renderScalar(value) {
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return `"${value.replaceAll("\\", "\\\\").replaceAll('"', '\\"')}"`;
}
function buildStartCommand(options) {
  const parts = [
    quote(options.dshBin),
    "--profile",
    quote(options.profileName)
  ];
  if (options.patchFile) {
    parts.push("--patch", quote(options.patchFile));
  }
  parts.push(
    // 绝不用 0.0.0.0：dsh webserver 自身不带 TLS 与认证围栏之外的保护，
    // 绑全网卡等于把 GUI 挂到网上
    "--host",
    "127.0.0.1",
    "--port",
    String(options.port),
    // 远端开浏览器没有意义，而且会在无 DISPLAY 的机器上报错
    "--no-open"
  );
  return parts.join(" ");
}

// src/provision/provisioner.ts
var DEFAULT_DSH_VERSION = "0.1.7-rc.2";
var TAG_PATTERN = /^[a-z]/i;
async function provision(transport, options) {
  const { signal } = options;
  options.onStageStart?.("\u63A2\u6D4B\u8FDC\u7AEF\u73AF\u5883");
  const probe = await probeRemote(transport, signal);
  assertDiskSpace(probe, transport.hostAlias);
  const paths = createRemotePaths(probe.homeDir);
  const ctx = { transport, paths };
  options.onStageDone?.(`${probe.platform.os}/${probe.platform.arch}`);
  const nodeVersion = options.nodeVersion ?? DEFAULT_NODE_VERSION;
  const alreadyHasNode = probe.managedNodes.some((node2) => node2.version === nodeVersion);
  let nodeMirrorUrl;
  if (alreadyHasNode) {
    options.onStageStart?.("Node \u53D1\u884C\u7248\u955C\u50CF\u6D4B\u901F");
    options.onStageSkip?.(`\u5DF2\u88C5 Node ${nodeVersion}`);
  } else {
    options.onStageStart?.("Node \u53D1\u884C\u7248\u955C\u50CF\u6D4B\u901F");
    const selection = await selectMirror(transport, "node", {
      cachePath: paths.mirrorCache,
      ...options.refreshMirrors ? { force: true } : {},
      ...signal ? { signal } : {}
    });
    nodeMirrorUrl = selection.selected.baseUrl;
    if (selection.fromCache) options.onStageSkip?.(`\u547D\u4E2D\u7F13\u5B58\uFF1A${selection.selected.name}`);
    else options.onStageDone?.(`\u9009\u4E2D ${selection.selected.name}`);
  }
  options.onStageStart?.(`\u51C6\u5907 Node ${nodeVersion}`);
  const node = await ensureNode(ctx, {
    version: nodeVersion,
    // 已装时不会用到 URL，给个占位避免把 undefined 传下去
    mirrorBaseUrl: nodeMirrorUrl ?? "",
    ...options.skipStabilityCheck ? { skipStabilityCheck: true } : {},
    ...signal ? { signal } : {}
  });
  options.onStageDone?.(node.reused ? "\u590D\u7528\u5DF2\u6709\u5B89\u88C5" : "\u5DF2\u5B89\u88C5");
  options.onStageStart?.("npm registry \u6D4B\u901F");
  const npmSelection = await selectMirror(transport, "npm", {
    cachePath: paths.mirrorCache,
    ...options.refreshMirrors ? { force: true } : {},
    ...signal ? { signal } : {}
  });
  if (npmSelection.fromCache) options.onStageSkip?.(`\u547D\u4E2D\u7F13\u5B58\uFF1A${npmSelection.selected.name}`);
  else options.onStageDone?.(`\u9009\u4E2D ${npmSelection.selected.name}`);
  const requested = options.dshVersion ?? DEFAULT_DSH_VERSION;
  let dshVersion = requested;
  if (TAG_PATTERN.test(requested)) {
    options.onStageStart?.(`\u89E3\u6790 dsh ${requested} \u6807\u7B7E`);
    dshVersion = await resolveDshVersion(ctx, {
      tag: requested,
      registryUrl: npmSelection.selected.baseUrl,
      nodeBinDir: node.binDir,
      ...signal ? { signal } : {}
    });
    options.onStageDone?.(`${requested} \u2192 ${dshVersion}`);
  }
  options.onStageStart?.(`\u51C6\u5907 dsh ${dshVersion}`);
  const dsh = await ensureDsh(ctx, {
    version: dshVersion,
    registryUrl: npmSelection.selected.baseUrl,
    nodeBinDir: node.binDir,
    ...signal ? { signal } : {}
  });
  options.onStageDone?.(dsh.reused ? "\u590D\u7528\u5DF2\u6709\u5B89\u88C5" : "\u5DF2\u5B89\u88C5");
  options.onStageStart?.("\u51C6\u5907 pnpm");
  const pnpm = await ensurePnpm(ctx, {
    registryUrl: npmSelection.selected.baseUrl,
    nodeBinDir: node.binDir,
    ...signal ? { signal } : {}
  });
  options.onStageDone?.(pnpm.reused ? "\u590D\u7528\u5DF2\u6709\u5B89\u88C5" : "\u5DF2\u5B89\u88C5");
  options.onStageStart?.("\u51C6\u5907\u4F1A\u8BDD profile");
  const profile = await prepareSessionProfile(ctx, {
    sessionId: options.sessionId,
    dshBin: dsh.dshBin,
    nodeBinDir: node.binDir,
    ...options.patches ? { patches: options.patches } : {},
    ...signal ? { signal } : {}
  });
  options.onStageDone?.(profile.reused ? "\u590D\u7528\u5DF2\u6709 profile" : "\u5DF2\u521B\u5EFA");
  return { paths, probe, node, dsh, profile };
}

